// Unit tests for src/crypto/p256_point/add.S (PLAN.MD Phase 16.3)
//
// add expected values are computed by a plain Python transliteration
// of the exact same formulas (no special-casing) used in the assembly,
// checked against a real ECC library (cryptography/OpenSSL) before this
// file was written -- see the commit that introduced p256_point.S. Since
// both sides use identical Jacobian formulas on identical inputs, the
// outputs must match bit-for-bit (Jacobian coordinates aren't unique in
// general, but here both sides start from the same X:Y:Z, so there's no
// representation ambiguity to worry about).

#include "test_harness.h"

extern void p256_fe_frombytes(uint64_t out[4], const uint8_t in[32])
    __asm__("p256_fe_frombytes");
extern void p256_fe_tobytes(uint8_t out[32], const uint64_t in[4])
    __asm__("p256_fe_tobytes");
extern void p256_point_add(uint8_t out[96], const uint8_t p1[96], const uint8_t p2[96])
    __asm__("p256_point_add");

// A Jacobian point as raw internal limb bytes (3 x 32 bytes,
// little-endian limbs, matching the fe internal representation) --
// built at test-init time from big-endian byte triples via frombytes,
// since the .S source works in limb form, not byte form.
struct jacbytes { uint8_t x[32], y[32], z[32]; };

static void jac_frombytes(uint8_t out[96], const struct jacbytes *j) {
    uint64_t t[4];
    p256_fe_frombytes(t, j->x); memcpy(out + 0, t, 32);
    p256_fe_frombytes(t, j->y); memcpy(out + 32, t, 32);
    p256_fe_frombytes(t, j->z); memcpy(out + 64, t, 32);
}

static int jac_tobytes_eq(const uint8_t got[96], const struct jacbytes *expect) {
    uint8_t b[32];
    p256_fe_tobytes(b, (const uint64_t *)(got + 0));
    if (memcmp(b, expect->x, 32) != 0) return 0;
    p256_fe_tobytes(b, (const uint64_t *)(got + 32));
    if (memcmp(b, expect->y, 32) != 0) return 0;
    p256_fe_tobytes(b, (const uint64_t *)(got + 64));
    if (memcmp(b, expect->z, 32) != 0) return 0;
    return 1;
}

